module top_module(clock,reset_n,enable);input clock, reset_n;
	output enable;

	reg [25:0] count;

	always@(posedge clock)
		begin
			if(!reset_n)
				count <= 26'd0;
			else
				begin
					if(count == 26'd400)
						count <= 26'd0;
					else
						count <= count + 1'b1;
				end
		end
	assign enable = (count == 26'd400) ? 1 : 0;endmodule

