description:
Design a reset generator circuit that produces a delayed active-low reset signal. The circuit uses a clock input and an active-low reset input to control the output reset signal. Upon receiving an active-low reset signal, the output is set high and a counter begins counting clock cycles. Once the counter reaches its maximum value, the output reset signal transitions to low, indicating that the system is ready to operate normally. This implementation ensures that the reset signal is asserted for a defined duration before allowing the system to resume operation.
module top_module(
		clk,
		reset_n_in,
		reset_out
	);

code:
module top_module(
		clk,
		reset_n_in,
		reset_out
	);parameter   CTR_WIDTH   =   16;

input 	    clk;	
input       reset_n_in;
output reg  reset_out;

reg		[CTR_WIDTH-1:0]		ctr;	


always	@(posedge clk or negedge reset_n_in)
begin
	if	(!reset_n_in)
	begin
		reset_out <= 1;
		ctr <= 0;
	end else begin
		if	(ctr == {CTR_WIDTH{1'b1}})
            reset_out <=  0;
		else begin
		    ctr <= ctr + 1'b1;
		    reset_out <= 1;
		end
	end
end

endmodule

