      count <= 4'h0;
      next_count <= 4'h0;
    end
    else begin
      if (enable == 1'b1) begin
        next_count <= count + 4'h1;
      end
      else begin
        next_count <= count;
      end

      count <= next_count;
    end
  end

endmodule

