module up_down_counter(
    input wire clk,
    input wire rst,
    input wire up_down,
    output reg [9:0] count
);

    always @(posedge clk) begin
        if (rst) begin
            count <= 10'b0;
        end else if (up_down) begin
            count <= count + 1;
        end else begin
            count <= count - 1;
        end
    end
endmodule

