module d_flip_flop(clk, clr, d, q);

    input clk;
    input clr;
    input d;
    output q;
    reg q;

    always @(posedge clk or posedge clr)
    begin
        if (clr)
            q <= 1'b0;
        else
            q <= d;
    end

endmodule

