module top_module(
  input ref_clk,
  input fb_clk,
  input ctrl,
  input reset,
  output reg clk_out
);parameter M = 2; // multiplication factor
parameter N = 1; // division factor
parameter F = 100; // frequency of the synchronized clock signal

reg [31:0] phase_accumulator;
reg [31:0] phase_increment;
reg [31:0] phase_difference;
reg [1:0] charge_pump_output;
reg [1:0] charge_pump_input;
reg [1:0] phase_detector_output;
reg [1:0] phase_detector_input;

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_accumulator <= 0;
    phase_increment <= 0;
    phase_difference <= 0;
    charge_pump_output <= 0;
    charge_pump_input <= 0;
    phase_detector_output <= 0;
    phase_detector_input <= 0;
  end else begin
    phase_increment <= ((M * 2**32) / (N * F));
    phase_accumulator <= phase_accumulator + phase_increment;
    phase_difference <= phase_accumulator - (fb_clk * 2**32 / ref_clk);
    phase_detector_input <= {phase_difference[31], phase_difference[0]};
  end
end

always @(posedge ctrl) begin
  if (phase_difference[31]) begin
    charge_pump_input <= 2'b10;
  end else if (phase_difference[0]) begin
    charge_pump_input <= 2'b01;
  end else begin
    charge_pump_input <= 2'b00;
  end
end

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    phase_detector_output <= 0;
  end else begin
    phase_detector_output <= phase_detector_input;
  end
end

always @(posedge ctrl) begin
  case (charge_pump_input)
    2'b10: charge_pump_output <= charge_pump_output - 2'b01;
    2'b01: charge_pump_output <= charge_pump_output + 2'b01;
    2'b00: charge_pump_output <= charge_pump_output;
  endcase
end

always @(posedge ref_clk or posedge reset) begin
  if (reset) begin
    clk_out <= 0;
  end else begin
    if (charge_pump_output[1]) begin
      clk_out <= ~clk_out;
    end
  end
end

endmodule

