module vending_machine (
	input clk,
	input resetn,
	input coin,
	output reg dispense);

	parameter IDLE=0, COIN_INSERTED=1, DISPENSE_ITEM=2;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			IDLE: next_state = coin ? COIN_INSERTED : IDLE;
			COIN_INSERTED: next_state = DISPENSE_ITEM;
			DISPENSE_ITEM: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	always @(state) begin
		case (state)
			DISPENSE_ITEM: dispense = 1;
			default: dispense = 0;
		endcase
	end
endmodule

